00064     public static function clearFolder($path, $exclude = array())
00065     {
00066         $result             = array();
00067         $result['return']   = true;
00068         $result['nb_files'] = 0;
00069 
00070         $handle = @opendir($path);
00071         if (!$handle) {
00072             return null;
00073         }
00074 
00075         while (false !== ($file = readdir($handle))) {
00076             if ($file == '.' || $file == '..' || in_array($file, $exclude)) {
00077                 continue;
00078             }
00079             if (is_dir($path . '/' . $file)) {
00080                 $r = self::clearFolder($path . '/' . $file);
00081                 if (!$r) {
00082                     $result['return'] = false;
00083 
00084                     return $result;
00085                 }
00086             } else {
00087                 $r = @unlink($path . '/' . $file);
00088                 if ($r) {
00089                     $result['nb_files']++;
00090                 } else {
00091                     $result['return'] = false;
00092 
00093                     return $result;
00094                 }
00095             }
00096         }
00097 
00098         closedir($handle);
00099 
00100         return $result;
00101     }
