00108     public static function deleteFolder($path)
00109     {
00110         if (is_dir($path)) {
00111             $path = rtrim($path, '/\\') . '/';
00112             $files = glob($path . '*', GLOB_MARK);
00113 
00114             if ($files === false) {
00115                 Log::error("deleteFolder(): Failed to glob path: " . $path);
00116                 return;
00117             }
00118 
00119             foreach ($files as $file) {
00120                 $normalizedFile = rtrim($file, '/\\');
00121 
00122                 if (is_link($normalizedFile)) {
00123                     if (!@unlink($normalizedFile) && !@rmdir($normalizedFile)) {
00124                         Log::error("deleteFolder(): Failed to unlink symlink: " . $normalizedFile);
00125                     }
00126                 } elseif (is_dir($file)) {
00127                     self::deleteFolder($file);
00128                 } else {
00129                     if (!@unlink($normalizedFile)) {
00130                         Log::error("deleteFolder(): Failed to unlink file: " . $normalizedFile);
00131                     }
00132                 }
00133             }
00134 
00135             if (!@rmdir($path)) {
00136                 // Only log error if directory still exists (might have been deleted by recursion)
00137                 if (is_dir($path)) {
00138                     Log::error("deleteFolder(): Failed to remove directory: " . $path);
00139                 }
00140             }
00141         }
00142     }
