00212     public static function isAdmin()
00213     {
00214         // Only applicable on Windows
00215         if (strtoupper(substr(PHP_OS, 0, 3)) !== 'WIN') {
00216             // On non-Windows systems, check if running as root
00217             if (function_exists('posix_geteuid')) {
00218                 return posix_geteuid() === 0;
00219             }
00220             // If we can't determine on non-Windows, assume true to avoid blocking
00221             return true;
00222         }
00223 
00224         // Method 1: Try using shell_exec with 'net session' command
00225         // This command only succeeds when run with admin privileges
00226         $output = CommandRunner::shellExec('net session 2>&1');
00227         if ($output !== null) {
00228             // Check for access denied errors
00229             if (stripos($output, 'Access is denied') !== false ||
00230                 stripos($output, 'System error 5') !== false ||
00231                 stripos($output, 'Zugriff verweigert') !== false) { // German
00232                 // Explicitly denied - not admin
00233                 return false;
00234             }
00235 
00236             // If we got output without errors, we likely have admin rights
00237             if (stripos($output, 'There are no entries') !== false ||
00238                 stripos($output, 'These workstations') !== false ||
00239                 preg_match('/\\\\\\\\/', $output)) {
00240                 return true;
00241             }
00242         }
00243 
00244         // Method 2: Check using whoami command (Windows Vista and later)
00245         $output = CommandRunner::shellExec('whoami /groups 2>&1');
00246         if ($output !== null && !empty($output)) {
00247             // Look for the Administrators group or High Mandatory Level
00248             if (stripos($output, 'S-1-16-12288') !== false || // High Mandatory Level
00249                 stripos($output, 'S-1-5-32-544') !== false) {  // Administrators group
00250                 return true;
00251             }
00252 
00253             // If we got output but no admin indicators, we're not admin
00254             if (stripos($output, 'S-1-16-8192') !== false) { // Medium Mandatory Level (not admin)
00255                 return false;
00256             }
00257         }
00258 
00259         // Method 3: Try to write to a system directory
00260         // This is a fallback method that checks if we can write to Windows directory
00261         $testFile = getenv('SystemRoot') . '\\Temp\\bearsampp_admin_test_' . uniqid() . '.tmp';
00262         $result = @file_put_contents($testFile, 'test');
00263         if ($result !== false) {
00264             @unlink($testFile);
00265             return true;
00266         }
00267 
00268         // If all methods fail or indicate no admin, return false
00269         return false;
00270     }
