00292     public static function replaceInFile($path, $replaceList)
00293     {
00294         if (file_exists($path)) {
00295             $lines = file($path);
00296             $fp    = fopen($path, 'w');
00297             foreach ($lines as $nb => $line) {
00298                 $replaceDone = false;
00299                 foreach ($replaceList as $regex => $replace) {
00300                     if (preg_match($regex, $line, $matches)) {
00301                         $currentReplace = $replace;
00302                         $countParams = preg_match_all('/{{(\d+)}}/', $currentReplace, $paramsMatches);
00303                         if ($countParams > 0 && $countParams <= count($matches)) {
00304                             foreach ($paramsMatches[1] as $paramsMatch) {
00305                                 $currentReplace = str_replace('{{' . $paramsMatch . '}}', $matches[$paramsMatch], $currentReplace);
00306                             }
00307                         }
00308                         Log::trace('Replace in file ' . $path . ' :');
00309                         Log::trace('## line_num: ' . trim($nb));
00310                         Log::trace('## old: ' . trim($line));
00311                         Log::trace('## new: ' . trim($currentReplace));
00312                         
00313                         // Preserve original line ending if present in $line
00314                         $ending = (preg_match("/\r\n$/", $line)) ? "\r\n" : (preg_match("/\n$/", $line) ? "\n" : "");
00315                         fwrite($fp, rtrim($currentReplace) . $ending);
00316 
00317                         $replaceDone = true;
00318                         break;
00319                     }
00320                 }
00321                 if (!$replaceDone) {
00322                     fwrite($fp, $line);
00323                 }
00324             }
00325             fclose($fp);
00326         }
00327     }
