00337     public static function getVersionList($path)
00338     {
00339         $result = array();
00340 
00341         $handle = @opendir($path);
00342         if (!$handle) {
00343             return false;
00344         }
00345 
00346         $prefix = basename($path);
00347 
00348         while (false !== ($file = readdir($handle))) {
00349             $filePath = $path . '/' . $file;
00350             if ($file != '.' && $file != '..' && is_dir($filePath) && $file != 'current') {
00351                 if (strpos($file, $prefix) === 0) {
00352                     $version = substr($file, strlen($prefix));
00353                 } else {
00354                     $version = $file;
00355                 }
00356                 $result[] = $version;
00357             }
00358         }
00359 
00360         closedir($handle);
00361         natcasesort($result);
00362 
00363         return $result;
00364     }
