00442     public static function findRepos($initPath, $startPath, $checkFile, $maxDepth = 1)
00443     {
00444         $depth  = substr_count(str_replace($initPath, '', $startPath), '/');
00445         $result = array();
00446 
00447         $handle = @opendir($startPath);
00448         if (!$handle) {
00449             return $result;
00450         }
00451 
00452         while (false !== ($file = readdir($handle))) {
00453             if ($file == '.' || $file == '..') {
00454                 continue;
00455             }
00456             if (is_dir($startPath . '/' . $file) && ($initPath == $startPath || $depth <= $maxDepth)) {
00457                 $tmpResults = self::findRepos($initPath, $startPath . '/' . $file, $checkFile, $maxDepth);
00458                 foreach ($tmpResults as $tmpResult) {
00459                     $result[] = $tmpResult;
00460                 }
00461             } elseif (is_file($startPath . '/' . $checkFile) && !in_array($startPath, $result)) {
00462                 $result[] = Path::formatUnixPath($startPath);
00463             }
00464         }
00465 
00466         closedir($handle);
00467 
00468         return $result;
00469     }
