00602     public static function getFilesToScan($path = null, $useCache = true, $forceRefresh = false)
00603     {
00604         // Generate cache key based on path parameter
00605         $cacheKey = md5(serialize($path));
00606 
00607         // Try to get from cache if enabled and not forcing refresh
00608         if ($useCache && !$forceRefresh) {
00609             $cachedResult = Cache::get($cacheKey);
00610             if ($cachedResult !== false) {
00611                 Cache::recordHit();
00612                 Log::debug('File scan cache HIT (saved expensive scan operation)');
00613                 return $cachedResult;
00614             }
00615         }
00616 
00617         Cache::recordMiss();
00618         Log::debug('File scan cache MISS (performing full scan)');
00619 
00620         // Perform the actual scan
00621         $startTime = self::getMicrotime();
00622         $result      = array();
00623         $pathsToScan = !empty($path) ? $path : self::getPathsToScan();
00624 
00625         foreach ($pathsToScan as $pathToScan) {
00626             $pathStartTime = self::getMicrotime();
00627             $findFiles = self::findFiles($pathToScan['path'], $pathToScan['includes'], $pathToScan['recursive']);
00628             foreach ($findFiles as $findFile) {
00629                 $result[] = $findFile;
00630             }
00631             Log::debug($pathToScan['path'] . ' scanned in ' . round(self::getMicrotime() - $pathStartTime, 3) . 's');
00632         }
00633 
00634         $totalTime = round(self::getMicrotime() - $startTime, 3);
00635         Log::info('Full file scan completed in ' . $totalTime . 's (' . count($result) . ' files found)');
00636 
00637         // Store in cache if enabled
00638         if ($useCache) {
00639             Cache::set($cacheKey, $result);
00640         }
00641 
00642         return $result;
00643     }
