00835     private static function findFiles($startPath, $includes = array(''), $recursive = true)
00836     {
00837         $result = array();
00838 
00839         $handle = @opendir($startPath);
00840         if (!$handle) {
00841             return $result;
00842         }
00843 
00844         while (false !== ($file = readdir($handle))) {
00845             if ($file == '.' || $file == '..') {
00846                 continue;
00847             }
00848             if (is_dir($startPath . '/' . $file) && $recursive) {
00849                 $tmpResults = self::findFiles($startPath . '/' . $file, $includes);
00850                 foreach ($tmpResults as $tmpResult) {
00851                     $result[] = $tmpResult;
00852                 }
00853             } elseif (is_file($startPath . '/' . $file)) {
00854                 foreach ($includes as $include) {
00855                     if (UtilString::startWith($include, '!')) {
00856                         $include = ltrim($include, '!');
00857                         if (UtilString::startWith($file, '.') && !UtilString::endWith($file, $include)) {
00858                             $result[] = Path::formatUnixPath($startPath . '/' . $file);
00859                         } elseif ($file != $include) {
00860                             $result[] = Path::formatUnixPath($startPath . '/' . $file);
00861                         }
00862                     } elseif (UtilString::endWith($file, $include) || $file == $include || empty($include)) {
00863                         $result[] = Path::formatUnixPath($startPath . '/' . $file);
00864                     }
00865                 }
00866             }
00867         }
00868 
00869         closedir($handle);
00870 
00871         return $result;
00872     }
