00979     public static function humanFileSize(int $size, string $unit = ''): string
00980     {
00981         // Forced unit mode
00982         if ($unit !== '') {
00983             return match ($unit) {
00984                 'GB' => number_format($size / (1 << 30), 2) . 'GB',
00985                 'MB' => number_format($size / (1 << 20), 2) . 'MB',
00986                 'KB' => number_format($size / (1 << 10), 2) . 'KB',
00987                 default => number_format($size) . ' bytes',
00988             };
00989         }
00990 
00991         // Native PHP 8.3+ auto-selection
00992         return human_readable_size($size, precision: 2);
00993     }
