01015     public static function getHttpHeaders($pingUrl)
01016     {
01017         if (function_exists('curl_version')) {
01018             $result = self::getCurlHttpHeaders($pingUrl);
01019         } else {
01020             $result = self::getFopenHttpHeaders($pingUrl);
01021         }
01022 
01023         if (!empty($result)) {
01024             $rebuildResult = array();
01025             foreach ($result as $row) {
01026                 $row = trim($row);
01027                 if (!empty($row)) {
01028                     $rebuildResult[] = $row;
01029                 }
01030             }
01031             $result = $rebuildResult;
01032 
01033             Log::debug('getHttpHeaders:');
01034             foreach ($result as $header) {
01035                 Log::debug('-> ' . $header);
01036             }
01037         }
01038 
01039         return $result;
01040     }
