01053     public static function getFopenHttpHeaders($url)
01054     {
01055         $result = array();
01056 
01057         $context = stream_context_create(array(
01058             'ssl' => array(
01059                 'verify_peer'       => false,
01060                 'verify_peer_name'  => false,
01061                 'allow_self_signed' => true,
01062             )
01063         ));
01064 
01065         $fp = @fopen($url, 'r', false, $context);
01066         if ($fp) {
01067             $meta   = stream_get_meta_data($fp);
01068             $result = isset($meta['wrapper_data']) ? $meta['wrapper_data'] : $result;
01069             fclose($fp);
01070         }
01071 
01072         return $result;
01073     }
01074 
01086     public static function getCurlHttpHeaders($url)
01087     {
01088         $result = array();
01089 
01090         $ch = curl_init();
01091         curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
01092         curl_setopt($ch, CURLOPT_VERBOSE, true);
01093         curl_setopt($ch, CURLOPT_HEADER, true);
01094         curl_setopt($ch, CURLOPT_URL, $url);
01095         curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);
01096 
01097         $response = @curl_exec($ch);
01098         if (empty($response)) {
01099             return $result;
01100         }
01101 
01102         Log::trace('getCurlHttpHeaders:' . $response);
01103         $responseHeaders = explode("\r\n\r\n", $response, 2);
01104         if (!isset($responseHeaders[0]) || empty($responseHeaders[0])) {
01105             return $result;
01106         }
01107 
01108         return explode("\n", $responseHeaders[0]);
01109     }
01110 
01124     public static function getHeaders($host, $port, $ssl = false)
01125     {
01126         $result  = array();
01127         $context = stream_context_create(array(
01128             'ssl' => array(
01129                 'verify_peer'       => false,
01130                 'verify_peer_name'  => false,
01131                 'allow_self_signed' => true,
01132             )
01133         ));
01134 
01135         $fp = @stream_socket_client(($ssl ? 'ssl://' : '') . $host . ':' . $port, $errno, $errstr, 5, STREAM_CLIENT_CONNECT, $context);
01136         if ($fp) {
01137             $out    = fgets($fp);
01138             $result = explode(PHP_EOL, $out);
01139             @fclose($fp);
01140         }
01141 
01142         if (!empty($result)) {
01143             $rebuildResult = array();
01144             foreach ($result as $row) {
01145                 $row = trim($row);
01146                 if (!empty($row)) {
01147                     $rebuildResult[] = $row;
01148                 }
01149             }
01150             $result = $rebuildResult;
01151 
01152             Log::debug('getHeaders:');
01153             foreach ($result as $header) {
01154                 Log::debug('-> ' . $header);
01155             }
01156         }
01157 
01158         return $result;
01159     }
