01168     public static function getApiJson($url)
01169     {
01170         $header = self::setupCurlHeaderWithToken();
01171 
01172         $ch = curl_init();
01173         curl_setopt($ch, CURLOPT_SSLVERSION, CURL_SSLVERSION_TLSv1_2);
01174         curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
01175         curl_setopt($ch, CURLOPT_VERBOSE, true);
01176         curl_setopt($ch, CURLOPT_URL, $url);
01177         curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);
01178         curl_setopt($ch, CURLOPT_HTTPHEADER, $header);
01179         $data = curl_exec($ch);
01180         if (curl_errno($ch)) {
01181             Log::error('CURL Error: ' . curl_error($ch));
01182         }
01183 
01184         // curl_close() is deprecated in PHP 8.5+ as it has no effect since PHP 8.0
01185         // The resource is automatically closed when it goes out of scope
01186         if (PHP_VERSION_ID < 80500) {
01187             curl_close($ch);
01188         }
01189 
01190         return trim($data);
01191     }
