01200     public static function isPortInUse($port)
01201     {
01202         // Set localIP statically
01203         $localIP = '127.0.0.1';
01204 
01205         // Save current error reporting level
01206         $errorReporting = error_reporting();
01207 
01208         // Disable error reporting temporarily
01209         error_reporting(0);
01210 
01211         $connection = @fsockopen($localIP, $port);
01212 
01213         // Restore original error reporting level
01214         error_reporting($errorReporting);
01215 
01216         if (is_resource($connection)) {
01217             fclose($connection);
01218             $process = Batch::getProcessUsingPort($port);
01219 
01220             return $process != null ? $process : 'N/A';
01221         }
01222 
01223         return false;
01224     }
