01248     public static function installService($bin, $port, $syntaxCheckCmd, $showWindow = false)
01249     {
01250         global $bearsamppLang, $bearsamppWinbinder;
01251 
01252         if (method_exists($bin, 'initData')) {
01253             $bin->initData();
01254         }
01255 
01256         $name     = $bin->getName();
01257         $service  = $bin->getService();
01258         $boxTitle = sprintf($bearsamppLang->getValue(Lang::INSTALL_SERVICE_TITLE), $name);
01259 
01260         $isPortInUse = self::isPortInUse($port);
01261         if ($isPortInUse === false) {
01262             if (!$service->isInstalled()) {
01263                 $service->create();
01264                 if ($service->start()) {
01265                     Log::info(sprintf('%s service successfully installed. (name: %s ; port: %s)', $name, $service->getName(), $port));
01266                     if ($showWindow) {
01267                         $bearsamppWinbinder->messageBoxInfo(
01268                             sprintf($bearsamppLang->getValue(Lang::SERVICE_INSTALLED), $name, $service->getName(), $port),
01269                             $boxTitle
01270                         );
01271                     }
01272 
01273                     return true;
01274                 } else {
01275                     $serviceError    = sprintf($bearsamppLang->getValue(Lang::SERVICE_INSTALL_ERROR), $name);
01276                     $serviceErrorLog = sprintf('Error during the installation of %s service', $name);
01277                     if (!empty($syntaxCheckCmd)) {
01278                         $cmdSyntaxCheck = $bin->getCmdLineOutput($syntaxCheckCmd);
01279                         if (!$cmdSyntaxCheck['syntaxOk']) {
01280                             $serviceError    .= PHP_EOL . sprintf($bearsamppLang->getValue(Lang::STARTUP_SERVICE_SYNTAX_ERROR), $cmdSyntaxCheck['content']);
01281                             $serviceErrorLog .= sprintf(' (conf errors detected : %s)', $cmdSyntaxCheck['content']);
01282                         }
01283                     }
01284                     Log::error($serviceErrorLog);
01285                     if ($showWindow) {
01286                         $bearsamppWinbinder->messageBoxError($serviceError, $boxTitle);
01287                     }
01288                 }
01289             } else {
01290                 Log::warning(sprintf('%s service already installed', $name));
01291                 if ($showWindow) {
01292                     $bearsamppWinbinder->messageBoxWarning(
01293                         sprintf($bearsamppLang->getValue(Lang::SERVICE_ALREADY_INSTALLED), $name),
01294                         $boxTitle
01295                     );
01296                 }
01297 
01298                 return true;
01299             }
01300         } elseif ($service->isRunning()) {
01301             Log::warning(sprintf('%s service already installed and running', $name));
01302             if ($showWindow) {
01303                 $bearsamppWinbinder->messageBoxWarning(
01304                     sprintf($bearsamppLang->getValue(Lang::SERVICE_ALREADY_INSTALLED), $name),
01305                     $boxTitle
01306                 );
01307             }
01308 
01309             return true;
01310         } else {
01311             Log::error(sprintf('Port %s is used by an other application : %s', $port, $isPortInUse));
01312             if ($showWindow) {
01313                 $bearsamppWinbinder->messageBoxError(
01314                     sprintf($bearsamppLang->getValue(Lang::PORT_NOT_USED_BY), $port, $isPortInUse),
01315                     $boxTitle
01316                 );
01317             }
01318         }
01319 
01320         return false;
01321     }
