01331     public static function removeService($service, $name)
01332     {
01333         if (!($service instanceof Win32Service)) {
01334             Log::error('$service not an instance of Win32Service');
01335 
01336             return false;
01337         }
01338 
01339         if ($service->isInstalled()) {
01340             if ($service->delete()) {
01341                 Log::info(sprintf('%s service successfully removed', $name));
01342 
01343                 return true;
01344             } else {
01345                 Log::error(sprintf('Error during the uninstallation of %s service', $name));
01346 
01347                 return false;
01348             }
01349         } else {
01350             Log::warning(sprintf('%s service does not exist', $name));
01351         }
01352 
01353         return true;
01354     }
