01365     public static function startService($bin, $syntaxCheckCmd, $showWindow = false)
01366     {
01367         global $bearsamppLang, $bearsamppWinbinder;
01368 
01369         if (method_exists($bin, 'initData')) {
01370             $bin->initData();
01371         }
01372 
01373         $name     = $bin->getName();
01374         $service  = $bin->getService();
01375         $boxTitle = sprintf($bearsamppLang->getValue(Lang::START_SERVICE_TITLE), $name);
01376 
01377         if (!$service->start()) {
01378             $serviceError    = sprintf($bearsamppLang->getValue(Lang::START_SERVICE_ERROR), $name);
01379             $serviceErrorLog = sprintf('Error while starting the %s service', $name);
01380             if (!empty($syntaxCheckCmd)) {
01381                 $cmdSyntaxCheck = $bin->getCmdLineOutput($syntaxCheckCmd);
01382                 if (!$cmdSyntaxCheck['syntaxOk']) {
01383                     $serviceError    .= PHP_EOL . sprintf($bearsamppLang->getValue(Lang::STARTUP_SERVICE_SYNTAX_ERROR), $cmdSyntaxCheck['content']);
01384                     $serviceErrorLog .= sprintf(' (conf errors detected : %s)', $cmdSyntaxCheck['content']);
01385                 }
