01408     public static function getGithubUrl($type = 'user', $user = APP_GITHUB_USER, $repo = null, $branch = null, $path = null) {
01409         if (empty($user) || !is_string($user)) {
01410             return false;
01411         }
01412 
01413         // Encode as URL path segment (not query encoding)
01414         $user = rawurlencode($user);
01415 
01416         switch ($type) {
01417             case 'user':
01418                 return "https://github.com/{$user}";
01419 
01420             case 'repo':
01421                 if (empty($repo) || !is_string($repo)) {
01422                     return false;
01423                 }
01424                 $repo = rawurlencode($repo);
01425                 return "https://github.com/{$user}/{$repo}";
01426 
01427             case 'raw':
01428                 if (empty($repo) || empty($branch) || empty($path) || !is_string($repo) || !is_string($branch) || !is_string($path)) {
01429                     return false;
01430                 }
01431                 $repo = rawurlencode($repo);
01432                 $branch = rawurlencode($branch);
01433 
01434                 $path = ltrim($path, '/');
01435                 $segments = array_map('rawurlencode', explode('/', $path));
01436                 $pathEncoded = implode('/', $segments);
01437 
01438                 return "https://raw.githubusercontent.com/{$user}/{$repo}/{$branch}/{$pathEncoded}";
01439 
01440             default:
01441                 return false;
01442         }
01443     }
01444 
