01482     public static function getFolderList($path)
01483     {
01484         $result = array();
01485 
01486         $handle = @opendir($path);
01487         if (!$handle) {
01488             return false;
01489         }
01490 
01491         while (false !== ($file = readdir($handle))) {
01492             $filePath = $path . '/' . $file;
01493             if ($file != '.' && $file != '..' && is_dir($filePath) && $file != 'current') {
01494                 $result[] = $file;
01495             }
01496         }
01497 
01498         closedir($handle);
01499         natcasesort($result);
01500 
01501         return $result;
01502     }
